import{_ as e,o as s,c as n,S as t}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse('{"title":"关于JavaScript跨域请求的相关知识","description":"2016 年已经过了 3 个月了,还没来得及更新博客...实在是惭愧惭愧...最近确实也很忙,一边要打工,一边要写论文,一边还要找工作...","frontmatter":{"title":"关于JavaScript跨域请求的相关知识","date":"2016-03-21 14:33","comments":true,"archives":2016,"tags":["js"]},"headers":[],"relativePath":"posts/2016-03-21-cors-options-method/index.md","filePath":"posts/2016/2016-03-21-CORS-options-method.md"}'),r={name:"posts/2016-03-21-cors-options-method/index.md"};function p(i,a,l,o,c,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<p>2016 年已经过了 3 个月了,还没来得及更新博客...实在是惭愧惭愧...最近确实也很忙,一边要打工,一边要写论文,一边还要找工作...</p><p>最近百度的导出插件出了点小问题,导致很多人无法正常和 Aria2c 通讯.经过仔细的分析,发现问题出在跨域请求上,接下来就要详细说说 JavaScript 的跨域请求.</p><h2 id="javascript-跨域请求" tabindex="-1">JavaScript 跨域请求 <a class="header-anchor" href="#javascript-跨域请求" aria-label="Permalink to &quot;JavaScript 跨域请求&quot;">​</a></h2><p>跨域请求指得是发起请求的资源所在域不同于该请求所指向资源所在的域的 HTTP 请求.最常见的就是跨域载入图片,我们可以看到很多网站主站和网站所使用的图片 是不同的域名的.这样做的好处是请求图片的时候不会发送主站的 Cookies,因为不同域名嘛.而且还可以减少主站的服务器压力.但载入图片使用的是 GET 方法,比较简单.</p><h2 id="跨域-post-请求" tabindex="-1">跨域 POST 请求 <a class="header-anchor" href="#跨域-post-请求" aria-label="Permalink to &quot;跨域 POST 请求&quot;">​</a></h2><p>我们经常使用 POST 请求发送各种指令数据,因为 POST 发送的数据没有长度限制.我们还可以在发送数据之前修改请求头,发送各种自定义的 HTTP Request Headers.但是 在跨域请求的时候 POST 的请求头被严格限制,被允许设置的请求头只有:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>- Accept</span></span>
<span class="line"><span>- Accept-Language</span></span>
<span class="line"><span>- Content-Language</span></span>
<span class="line"><span>- Content-Type</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>并且允许的 Content-Type 只有一下三种:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>- application/x-www-form-urlencoded</span></span>
<span class="line"><span>- multipart/form-data</span></span>
<span class="line"><span>- text/plain</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="preflighted-requests" tabindex="-1">Preflighted requests <a class="header-anchor" href="#preflighted-requests" aria-label="Permalink to &quot;Preflighted requests&quot;">​</a></h2><p>当我们发送的请求不满足上面的条件时,就必须发送预请求给目的站点,来查明这个跨站请求对于目的站点是不是安全可接受的。以下条件会触发预请求的发送:</p><ul><li>请求以 GET, HEAD 或者 POST 以外的方法发起请求。或者使用 POST，但请求数据为 application/x-www-form-urlencoded, multipart/form-data 或者 text/plain 以外的数据类型。比如说，用 POST 发送数据类型为 application/xml 或者 text/xml 的 XML 数据的请求。</li><li>使用自定义请求头（例如 Aria2c 的验证使用的 Authorization）</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>本次 BUG 的出现,是由于代码验证不规范,对于不需要用户名和密码验证的 RPC 地址.仍然发送自定义的 Authorization 验证头.导致触发 OPTIONS 请求,但是本身不支持验证的 Aria2c 客户端无法识别 OPTIONS 请求,只能返回 500 错误.导致通讯失败,至此 BUG 分析完毕.</p><h2 id="参考" tabindex="-1">参考: <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考:&quot;">​</a></h2><p><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Access_control_CORS" target="_blank" rel="noreferrer">HTTP access control (CORS)</a></p><p><a href="https://www.w3.org/Protocols/rfc2616/rfc2616-sec9.html" target="_blank" rel="noreferrer">HTTP/1.1: Method Definitions</a></p>`,17)])])}const m=e(r,[["render",p]]);export{u as __pageData,m as default};
